contract InvMutTest {
    C c;
    bool public callbackReverts;
    bool public callbackEntered;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, uint v, bool makeCallbackRevert) public payable {
        callbackReverts = makeCallbackRevert;
        callbackEntered = false;
        address[] memory tos = new address[](1);
        tos[0] = address(this);
        bool reverted;
        try c.transfer(from, address(this), tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(callbackEntered == reverted || !callbackEntered);
    }

    receive() external payable {}

    fallback() external payable {
        callbackEntered = true;
        if (callbackReverts) {
            revert();
        }
        c.transfer(address(this), address(this), new address[](0), 0);
    }
}

